INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvem var Martin Luther?","options":["En tysk praest der protesterede mod den katolske kirkes praksis i 1517","En dansk biskop der grundlagde den protestantiske kirke","En tysk kejser der forjoede paven fra Europa","En dansk praest der oversatte bibelen til latin"],"correct":"En tysk praest der protesterede mod den katolske kirkes praksis i 1517","accepted_answers":["En tysk praest der protesterede mod den katolske kirkes praksis i 1517"],"review_text":"Martin Luther var en tysk praest. Han protesterede mod den katolske kirke i 1517. Hans ideer spredte sig hurtigt og startede Reformationen i Europa."}'::jsonb,
  'mc','short','{"concepts":["Martin Luther","Reformationen","protestantisme","1517"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Reformationen?","options":["En religioes og politisk bevaegelse der brued med den katolske kirke og skabte den protestantiske kirke","En reform af den katolske kirke som paven godkendte","En krig mellem England og Frankrig om retten til at vaere kristen","En bevaegelse der ville afskaffe al religion i Europa"],"correct":"En religioes og politisk bevaegelse der brued med den katolske kirke og skabte den protestantiske kirke","accepted_answers":["En religioes og politisk bevaegelse der brued med den katolske kirke og skabte den protestantiske kirke"],"review_text":"Reformationen startede som en religioes protest men blev ogsaa en politisk bevaegelse. Den brued med den katolske kirke i Rom og skabte nye protestantiske kirker i Europa."}'::jsonb,
  'mc','short','{"concepts":["Reformationen","protestantisme","katolsk kirke","kirkehistorie"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad kritiserede Martin Luther i den katolske kirke?","options":["At kirken solgte afladsbreve der lovede syndernes tilgivelse mod betaling","At kirken havde for faae kirker i Europa","At kirken brugte for mange penge paa fattigpleje","At kirken laeste for meget i bibelen"],"correct":"At kirken solgte afladsbreve der lovede syndernes tilgivelse mod betaling","accepted_answers":["At kirken solgte afladsbreve der lovede syndernes tilgivelse mod betaling"],"review_text":"Afladsbreve var papirbeviser den katolske kirke solgte. De lovede syndernes tilgivelse mod betaling. Luther mente det var forkert at kobe sig til Guds naade. Kun tro kunne give tilgivelse."}'::jsonb,
  'mc','short','{"concepts":["afladsbreve","kritik","Luther","naade","betaling"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad kendetegnede den nye protestantiske kirke?","options":["Gudstjeneste paa folkets eget sprog og fokus paa bibelen fremfor pavens autoritet","Gudstjeneste paa latin og direkte linje til paven i Rom","Ingen kirker eller praester folk bad alene derhjemme","Kirker der kun var aabne om sondagen og ellers lukkede"],"correct":"Gudstjeneste paa folkets eget sprog og fokus paa bibelen fremfor pavens autoritet","accepted_answers":["Gudstjeneste paa folkets eget sprog og fokus paa bibelen fremfor pavens autoritet"],"review_text":"I den katolske kirke var gudstjenesten paa latin som de fleste ikke forstod. I den protestantiske kirke horte folk gudstjenesten paa deres eget sprog. Bibelen var nu tilgaengelig for alle og ikke kun for praesterne."}'::jsonb,
  'mc','short','{"concepts":["protestantisme","folkesprog","bibelen","gudstjeneste"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad gjoerde Christian III i forbindelse med Reformationen i Danmark?","options":["Han indfoerte den lutherske reformation i Danmark i 1536 og blev kirkens overhoved","Han afviste Reformationen og forblev katolik","Han overlod beslutningen til den danske befolkning","Han inviterede paven til Danmark for at lede kirken"],"correct":"Han indfoerte den lutherske reformation i Danmark i 1536 og blev kirkens overhoved","accepted_answers":["Han indfoerte den lutherske reformation i Danmark i 1536 og blev kirkens overhoved"],"review_text":"I 1536 indfoerte Christian III den lutherske reformation i Danmark. Kongen overtog kontrollen over kirken. De katolske biskopper mistede deres magt. Danmark blev et luthersk land."}'::jsonb,
  'mc','short','{"concepts":["Christian III","dansk Reformation","1536","kirkens overhoved"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad aendrede sig i hverdagen for en dansk borger efter Reformationen i 1536?","options":["Gudstjenesten skete nu paa dansk og ikke paa latin og kongen var nu kirkens overhoved fremfor paven","Folk behoevede ikke laengere gaa i kirke","Alle kirker blev revet ned og bygget op igen","Religion forsvandt fuldstaendigt fra hverdagen"],"correct":"Gudstjenesten skete nu paa dansk og ikke paa latin og kongen var nu kirkens overhoved fremfor paven","accepted_answers":["Gudstjenesten skete nu paa dansk og ikke paa latin og kongen var nu kirkens overhoved fremfor paven"],"review_text":"For den menige borger var den stoerste forskel at gudstjenesten nu var paa dansk. Man forstod hvad praesten sagde. Paven i Rom havde ikke laengere nogen magt i Danmark. Kongen var nu kirkens overhoved."}'::jsonb,
  'mc','short','{"concepts":["hverdagsliv","gudstjeneste","dansk sprog","Reformation"],"misconception_type":"overgeneralization","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',6,1
);

