INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor slog Martin Luther sine 95 teser op paa kirkedoren i Wittenberg i 1517?","options":["For at invitere til offentlig diskussion om den katolske kirkes brug af afladsbreve","For at opsige sin stilling som praest","For at erklaere krig mod paven","For at reklamere for sin nye kirke"],"correct":"For at invitere til offentlig diskussion om den katolske kirkes brug af afladsbreve","accepted_answers":["For at invitere til offentlig diskussion om den katolske kirkes brug af afladsbreve"],"review_text":"I 1517 slog Luther 95 argumenter op paa kirkedoren i Wittenberg. Det var en invitation til akademisk diskussion. Han vidste ikke at hans ideer ville sprede sig saa hurtigt og skabe en revolution."}'::jsonb,
  'mc','short','{"concepts":["95 teser","Wittenberg","afladsbreve","diskussion"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med kirkens magt i Danmark efter Reformationen?","options":["Kirken mistede sin selvstaendige politiske og okonomiske magt og kom under kongens kontrol","Kirkens magt voksede fordi den protestantiske kirke var mere populaer","Kirken beholdt al sin magt men skiftede blot leder fra paven til en dansk biskop","Kirken mistede al indflydelse paa samfundet fuldstaendigt"],"correct":"Kirken mistede sin selvstaendige politiske og okonomiske magt og kom under kongens kontrol","accepted_answers":["Kirken mistede sin selvstaendige politiske og okonomiske magt og kom under kongens kontrol"],"review_text":"Den katolske kirke havde ejet enorme jordarealer og haft politisk magt. Efter Reformationen overtog kongen kirkens ejendomme. Kirken kom under kongens kontrol. Det styrkede kongens magt enormt."}'::jsonb,
  'mc','short','{"concepts":["kirkens magt","kongens magt","ejendom","Reformation"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor hjalp bogtrykkerkunsten Reformationen med at sprede sig hurtigt?","options":["Luthers skrifter kunne nu trykkes i tusindvis af eksemplarer og naae folk overalt i Europa","Bogtrykkerkunsten hjalp paven med at sende svar til Luther","Bogtrykkerkunsten muliggjorde kun skrivning paa latin","Bogtrykkerkunsten var ikke vigtig for Reformationen"],"correct":"Luthers skrifter kunne nu trykkes i tusindvis af eksemplarer og naae folk overalt i Europa","accepted_answers":["Luthers skrifter kunne nu trykkes i tusindvis af eksemplarer og naae folk overalt i Europa"],"review_text":"Foer bogtrykkerkunsten tog det maaneder at kopiere en bog i haand. Med trykkeriet kunne Luthers skrifter kopieres i tusindvis paa dage. Hans ideer spredte sig til hele Europa paa rekordtid."}'::jsonb,
  'mc','short','{"concepts":["bogtrykkeri","spredning","Luther","massekommunikation"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor stoettede mange europaeiske konger Reformationen?","options":["Fordi Reformationen gav kongen mulighed for at overtage kirkens rigdom og slippe fri af pavens autoritet","Fordi konger var dybe troende lutheranere der elskede Luthers teologi","Fordi paven bad konger om at stoette Reformationen","Fordi konger var bange for at folket ville tvinge dem"],"correct":"Fordi Reformationen gav kongen mulighed for at overtage kirkens rigdom og slippe fri af pavens autoritet","accepted_answers":["Fordi Reformationen gav kongen mulighed for at overtage kirkens rigdom og slippe fri af pavens autoritet"],"review_text":"Den katolske kirke ejede op til en tredjedel af al jord i Europa. Reformationen gav konger mulighed for at overtage kirkens ejendomme og saette sig fri af pavens politiske indflydelse. For mange konger var Reformationen ogsaa et magttrek."}'::jsonb,
  'mc','short','{"concepts":["konger","kirkens rigdom","paven","politisk magt"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med klostrenes og kirkens ejendomme i Danmark efter Reformationen?","options":["Kongen overtog dem og brugte indtagterne til at styrke statsmagten","Ejendommene blev delt ud til fattige borgere","Ejendommene forblev i kirkens haaende men under luthersk ledelse","Alle klostre og kirker blev brudt ned"],"correct":"Kongen overtog dem og brugte indtagterne til at styrke statsmagten","accepted_answers":["Kongen overtog dem og brugte indtagterne til at styrke statsmagten"],"review_text":"Det var enorme vaerdier. Klostre, gaarde og landsbyer som kirken ejede gik nu til kongen. Det gjorde kongen rig og svaekkede kirken. Reformationen var ikke bare en religioes begivenhed men ogsaa en okonomisk revolution."}'::jsonb,
  'mc','short','{"concepts":["klostre","kirkens ejendom","kongens rigdom","okonomisk revolution"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod Reformationen for de danske boender i praksis?","options":["Den religiose aendring kom men den soziale og okonomiske undertrykkelse fortsatte uaendret","Boender fik frihed og jord som beloening for at stoette Reformationen","Boender mistede al religion og det goerde livet svaerere","Boender fik stemmeret og politisk magt"],"correct":"Den religiose aendring kom men den soziale og okonomiske undertrykkelse fortsatte uaendret","accepted_answers":["Den religiose aendring kom men den soziale og okonomiske undertrykkelse fortsatte uaendret"],"review_text":"Boender horte nu gudstjenesten paa dansk og forstod den bedre. Men de ejede stadig ikke land. De betalte stadig afgifter. Den politiske og soziale forandring kom ikke til boenderne med Reformationen."}'::jsonb,
  'mc','short','{"concepts":["boender","Reformation","sozial uforandret","okonomisk undertrykkelse"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er enevaelde?","options":["Et styresystem hvor kongen har al lovgivende, udovende og dommende magt alene","Et styresystem hvor kongen deler magten med adelen og kirken","Et demokrati hvor folket valgte kongen hvert femte aar","Et system hvor kirken og kongen regerede side om side med ens magt"],"correct":"Et styresystem hvor kongen har al lovgivende, udovende og dommende magt alene","accepted_answers":["Et styresystem hvor kongen har al lovgivende, udovende og dommende magt alene"],"review_text":"Enevaelde betyder at kongen alene har al magt. Han laver lovene. Han udforer dem. Han er overdommer. Der er ingen parlement og ingen adel der kan blokere ham. Danmark fik enevaelde i 1660."}'::jsonb,
  'mc','short','{"concepts":["enevaelde","absolut monarki","kongens magt","1660"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',6,2
);

