INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at Reformationen kun var en religioes begivenhed?","options":["Reformationen aendrede ogsaa magtbalancen politisk og okonomisk ved at flytte kirkens rigdom og magt til fyrsterne","Forestillingen er korrekt Reformationen handlede kun om religion","Det er forkert fordi Reformationen var kun politisk og intet med religion at goere","Det er forkert fordi Reformationen kun paavirket adelen"],"correct":"Reformationen aendrede ogsaa magtbalancen politisk og okonomisk ved at flytte kirkens rigdom og magt til fyrsterne","accepted_answers":["Reformationen aendrede ogsaa magtbalancen politisk og okonomisk ved at flytte kirkens rigdom og magt til fyrsterne"],"review_text":"Reformationen aendrede ikke blot gudstjenesten. Den aendrede hvem der ejede jord og hvem der havde politisk autoritet. Konger i hele Europa fik et vaeldigt magtloeft da de overtog kirkens ejendomme og saatte sig fri af paven."}'::jsonb,
  'mc','short','{"concepts":["Reformation","politisk","okonomisk","kirkens rigdom","misconception-kun-religion"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvem profiterede mest paa den danske Reformation i 1536?","options":["Kongen som overtog kirkens ejendomme og blev kirkens overhoved og dermed svaekkede alle rivaler","Boenderne som fik fri jord og ikke laengere betalte tiende til kirken","Praesterne som fik hoejere loen og mere magt","Adelen som overtog alle klostre"],"correct":"Kongen som overtog kirkens ejendomme og blev kirkens overhoved og dermed svaekkede alle rivaler","accepted_answers":["Kongen som overtog kirkens ejendomme og blev kirkens overhoved og dermed svaekkede alle rivaler"],"review_text":"Christian III vandt enormt paa Reformationen. Han konfiskerede kirkens jord og klostrenes ejendomme. Han afsatte de katolske biskopper. Ingen rivalmagt i Danmark var laengere stor nok til at udfordre ham. Det var begyndelsen paa kongens vej mod enevaelde."}'::jsonb,
  'mc','short','{"concepts":["Christian III","vinder","kirkens ejendom","magtbalance","vejen mod enevaelde"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var forbindelsen mellem Reformationen og uddannelse?","options":["Luther insisterede paa at alle skulle kunne laese bibelen selv og det fremmede grundlaeggende skoleundervisning","Reformationen lukkede alle skoler fordi kirken ikke laengere kontrollerede undervisningen","Uddannelse var upaavirkede af Reformationen","Kun adelen fik bedre uddannelse resten mistede adgang"],"correct":"Luther insisterede paa at alle skulle kunne laese bibelen selv og det fremmede grundlaeggende skoleundervisning","accepted_answers":["Luther insisterede paa at alle skulle kunne laese bibelen selv og det fremmede grundlaeggende skoleundervisning"],"review_text":"Luther mente at alle troende selv skulle kunne laese bibelen. Det kraevede at folk kunne laese. Gradvist opstod skoler som laerte born at laese. Det var ikke universelt tilgaengeligt men Reformationen satte uddannelse paa dagsordenen."}'::jsonb,
  'mc','short','{"concepts":["uddannelse","laesning","bibelen","Reformation","skoler"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at kirken i middelalderen kun paavirket religiose anliggender?","options":["Kirken kontrollerede skole, hospital, kalender og politisk legitimitet og var samfundets mest indflydelsesrige institution","Forestillingen er korrekt kirken holdt sig til rent religiose anliggender","Kirken paavirket kun rige folk resten var uberort","Kirken var vigtig i byerne men naaede ikke ud til landsbyerne"],"correct":"Kirken kontrollerede skole, hospital, kalender og politisk legitimitet og var samfundets mest indflydelsesrige institution","accepted_answers":["Kirken kontrollerede skole, hospital, kalender og politisk legitimitet og var samfundets mest indflydelsesrige institution"],"review_text":"Kirken drev skoler og hospitaler. Den ejede jord. Den kontrollerede kalenderen. Den legitimerede kongers magt. At sige at kirken kun var religioes er at misforstaa hvad kirken var. Den var samfundets centrale institution."}'::jsonb,
  'mc','short','{"concepts":["kirkens rolle","skole","hospital","magt","misconception-kirken-kun-religion"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod det at leve under enevaelde for en dansk bonde i 1600-1700-tallet?","options":["Bonden var underlagt kongens love direkte men ejede stadig intet land og var bundet til godset","Bonden fik ejendomsret over den jord han dyrkede","Bonden fik mulighed for at klage direkte til kongen","Bondens liv forbedredes markant under enevaeldet"],"correct":"Bonden var underlagt kongens love direkte men ejede stadig intet land og var bundet til godset","accepted_answers":["Bonden var underlagt kongens love direkte men ejede stadig intet land og var bundet til godset"],"review_text":"Enevaeldet aendrede kongens magt men ikke bondens dagligdag. Bonden dyrkede stadig andres jord. Han betalte stadig afgifter. Den store politiske forandring i toppen aendrede ikke vilkaarene i bunden."}'::jsonb,
  'mc','short','{"concepts":["bonde","enevaelde","hverdagsliv","ingen forandring i bunden"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at alle i Danmark bejede Reformationen i 1536?","options":["De katolske biskopper blev arresteret og mange i kirken modsatte sig Reformationen som Christian III gennemtvang med magt","Forestillingen er korrekt alle bejede Reformationen med glaede","Det er forkert fordi ingen stoettede Reformationen","Det er forkert fordi Reformationen kom gradvist uden modstand"],"correct":"De katolske biskopper blev arresteret og mange i kirken modsatte sig Reformationen som Christian III gennemtvang med magt","accepted_answers":["De katolske biskopper blev arresteret og mange i kirken modsatte sig Reformationen som Christian III gennemtvang med magt"],"review_text":"Christian III gennemfoerte Reformationen ved at arrestere de katolske biskopper. Det var ikke en fredelig overgang. Dele af adelen og kirken modsatte sig. Reformationen var en magtmassig gennemtvingning ikke en frivillig kollektiv beslutning."}'::jsonb,
  'mc','short','{"concepts":["modstand","biskopper","Christian III","gennemtvingning","misconception-alle-stoettede"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad aendrede Reformationen ved det enkelte menneskes forhold til Gud?","options":["I katolsk tradition var praesten mellemled til Gud. I luthersk tro var der en direkte linje mellem den troende og Gud","Luthersk tro kraevede at man boede i et kloster for at naerme sig Gud","I luthersk tro behoevede man ikke laengere at tro paa Gud","Reformationen aendrede intet ved forholdet til Gud kun gudstjenestesproget"],"correct":"I katolsk tradition var praesten mellemled til Gud. I luthersk tro var der en direkte linje mellem den troende og Gud","accepted_answers":["I katolsk tradition var praesten mellemled til Gud. I luthersk tro var der en direkte linje mellem den troende og Gud"],"review_text":"I den katolske kirke gik man til Gud via praesten og sakramenterne. Luther sagde at troen alene var nok. Man behoevede ikke kirken som mellemled. Det var et fundamentalt skift i synet paa menneskets forhold til Gud og autoritet."}'::jsonb,
  'mc','short','{"concepts":["direkte linje","Gud","tro","praestens rolle","Reformation"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',6,3
);

-- ─── GRADE 6 · BAND 4 (5 questions) ─────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad tror du at en dansk bonde syntes om Reformationen i 1536?","options":["Blandet: gudstjenesten paa dansk var bedre men den okonomiske undertrykkelse og den manglende frihed fortsatte","Ren glaede fordi Reformationen frigjorde boenderne fra adelen","Ren modstand fordi boenderne elskede den katolske kirke","Ligegyldighed fordi religion ikke betod noget for boenderne"],"correct":"Blandet: gudstjenesten paa dansk var bedre men den okonomiske undertrykkelse og den manglende frihed fortsatte","accepted_answers":["Blandet: gudstjenesten paa dansk var bedre men den okonomiske undertrykkelse og den manglende frihed fortsatte"],"review_text":"Bonden horte nu gudstjenesten paa dansk og forstod den bedre. Men bonden ejede stadig intet. Han betalte stadig afgifter. Reformationen aendrede hvem der regerede religionen men ikke hvem der ejede landet. Fra bondens perspektiv var den okonomiske virkelighed uforandret."}'::jsonb,
  'mc','short','{"concepts":["bonde-perspektiv","Reformation","okonomisk virkelighed","gudstjeneste"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',6,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var de to vigtigste aarsager til at den katolske kirke mistede saa megen magt i 1500-tallets Europa?","options":["Intern korruption i kirken svaekkede dens trovaerdighed og fyrsters okonomiske interesse i at overtage kirkens rigdomme","Kirken valgte frivilligt at opgive sin magt for at fokusere paa spiritualitet","Befolkningerne tvang kirken ved revolution","Paven beordrede kirkerne til at overgive magten til fyrsterne"],"correct":"Intern korruption i kirken svaekkede dens trovaerdighed og fyrsters okonomiske interesse i at overtage kirkens rigdomme","accepted_answers":["Intern korruption i kirken svaekkede dens trovaerdighed og fyrsters okonomiske interesse i at overtage kirkens rigdomme"],"review_text":"Kirken var svaeekket indefra. Korrupte praester og afladshandelen underminerede trovaerdigheden. Dertil kom at konger og fyrster saa en stor okonomisk mulighed i kirkens enorme ejendomme. Begge kraefter bidrog til kirkens magtfald."}'::jsonb,
  'mc','short','{"concepts":["korruption","kirkens magt","fyrster","okonomisk interesse","trovaerdighed"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',6,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Luthers egentlige udfordring til den etablerede orden?","options":["Han sagde at den individuelle samvittighed og bibelen var autoritet over pavens og kirkens traditioner","Han sagde at konger burde afsaette paven militaert","Han sagde at al religion var forkert og burde afskaffes","Han sagde at kirken burde ejes af adelen og ikke af paven"],"correct":"Han sagde at den individuelle samvittighed og bibelen var autoritet over pavens og kirkens traditioner","accepted_answers":["Han sagde at den individuelle samvittighed og bibelen var autoritet over pavens og kirkens traditioner"],"review_text":"Luthers revolutionaere idé var enkel men farlig: bibelen og den personlige samvittighed er over kirkens tradition og pavens autoritet. Det udfordrede ikke blot religionen men hele den magtstruktur der var bygget paa kirkens monopol paa Guds ord."}'::jsonb,
  'mc','short','{"concepts":["individuel samvittighed","bibelen","autoritet","paven","revolution"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',6,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forbindelsen mellem Reformationens ide om individets samvittighed og den gradvise vej mod demokrati?","options":["Reformationen fremhaevede individets evne til at fortolke bibelen selv og saaede froe til ideen om at individet ogsaa kan have politiske rettigheder","Reformationen indfoerte straks demokrati i alle lutherske lande","Der er ingen forbindels Reformationen og demokrati er helt uafhaengige","Reformationen forhindrede demokrati fordi den styrkede kongens magt"],"correct":"Reformationen fremhaevede individets evne til at fortolke bibelen selv og saaede froe til ideen om at individet ogsaa kan have politiske rettigheder","accepted_answers":["Reformationen fremhaevede individets evne til at fortolke bibelen selv og saaede froe til ideen om at individet ogsaa kan have politiske rettigheder"],"review_text":"Luthers ide om den individuelle samvittighed som autoritet var subversiv. Hvis den enkelt kan fortolke bibelen selv hvem sagde saa at han ikke ogsaa kan have en mening om politik? Det var ikke en direkte vej men froe der spirede over aarhundreder."}'::jsonb,
  'mc','short','{"concepts":["individuel samvittighed","demokrati","politiske rettigheder","langsigtede konsekvenser"],"misconception_type":"temporal_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',6,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var enevaeldet godt for det danske folk?","options":["Det afhang af hvem man spurgte: for borgerskabet gav det stabilitet men for adelen svaekkede det privilegier og for boenderne aendrede det naesten intet","Enevaeldet var godt for alle fordi kongen vaernede om alle borgeres interesser","Enevaeldet var skadeligt for alle fordi ingen kunne beklage sig","Enevaeldet var godt for adelen fordi de beholdt al magt"],"correct":"Det afhang af hvem man spurgte: for borgerskabet gav det stabilitet men for adelen svaekkede det privilegier og for boenderne aendrede det naesten intet","accepted_answers":["Det afhang af hvem man spurgte: for borgerskabet gav det stabilitet men for adelen svaekkede det privilegier og for boenderne aendrede det naesten intet"],"review_text":"Enevaeldet betod lov og orden og stabilitet som borgerskab og handel profiterede af. Adelen mistede sin politiske magt. Boenderne maerkede lidt forskel. Enevaelde var ikke simpelt godt eller ondt men et komplekst system med vindere og tabere."}'::jsonb,
  'mc','short','{"concepts":["enevaelde","perspektiver","borgerskab","adel","bonde"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',6,4
);;
